() => {
  const elements = Array.from(document.querySelectorAll('a'));
  const matches = elements
    .map(el => ({ text: el.textContent.trim(), href: el.href }))
    .filter(item => item.text.toLowerCase().includes('advanced security'));
  return matches;
}

() => {
  const elements = Array.from(document.querySelectorAll('a, h1, h2, h3, h4, p, span'));
  const matches = elements
    .map(el => ({ text: el.textContent.trim(), href: el.href || '', tag: el.tagName }))
    .filter(item => item.text && item.text.toLowerCase().includes('advanced security'));
  return matches;
}

() => {
  const elements = Array.from(document.querySelectorAll('a'));
  const links = elements
    .filter(el => el.textContent.trim().toLowerCase().includes('application security'));
  return links.map(a => ({ text: a.textContent.trim(), href: a.href }));
}

() => {
  const elements = Array.from(document.querySelectorAll('a'));
  const links = elements
    .filter(el => el.href && el.href.includes('resources'))
    .map(a => ({ text: a.textContent.trim(), href: a.href }));
  return links;
}

() => {
  // Find and try to close any overlay/modal
  const closeBtn = document.querySelector('[aria-label="Close"], .close-button, button.close');
  if (closeBtn) {
    closeBtn.click();
    return 'closed';
  }
  // Try clicking outside
  document.body.click();
  // Try escape key
  document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }));
  return 'attempted to close';
}

() => { 
  const heading = document.querySelector('h1');
  const h1 = heading ? heading.textContent.trim() : 'No h1 found';
  const allHeadings = Array.from(document.querySelectorAll('h1, h2, h3, h4')).map(h => h.textContent.trim());
  return { h1, allHeadings };
}

() => {
  const articles = Array.from(document.querySelectorAll('a[href*="/resources/articles/"]'));
  return articles.map(a => ({ text: a.textContent.trim(), href: a.getAttribute('href') }));
}

() => {
  const anchors = document.querySelectorAll('a[href*="/resources/articles/"]');
  return Array.from(anchors).map(a => ({ text: a.textContent.trim(), href: a.getAttribute('href') })).filter(a => a.text);
}
